func (t TrackingType) ValueFromObject(ctx context.Context, in basetypes.ObjectValue) (basetypes.ObjectValuable, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributes := in.Attributes()

	assignedCommentsAttribute, ok := attributes["assigned_comments"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`assigned_comments is missing from object`)

		return nil, diags
	}

	assignedCommentsVal, ok := assignedCommentsAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`assigned_comments expected to be basetypes.BoolValue, was: %T`, assignedCommentsAttribute))
	}

	checklistsAttribute, ok := attributes["checklists"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`checklists is missing from object`)

		return nil, diags
	}

	checklistsVal, ok := checklistsAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`checklists expected to be basetypes.BoolValue, was: %T`, checklistsAttribute))
	}

	subtasksAttribute, ok := attributes["subtasks"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`subtasks is missing from object`)

		return nil, diags
	}

	subtasksVal, ok := subtasksAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`subtasks expected to be basetypes.BoolValue, was: %T`, subtasksAttribute))
	}

	if diags.HasError() {
		return nil, diags
	}

	return TrackingValue{
		AssignedComments: assignedCommentsVal,
		Checklists:       checklistsVal,
		Subtasks:         subtasksVal,
		state:            attr.ValueStateKnown,
	}, diags
}

