func NewTrackingValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (TrackingValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing TrackingValue Attribute Value",
				"While creating a TrackingValue value, a missing attribute value was detected. "+
					"A TrackingValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("TrackingValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid TrackingValue Attribute Type",
				"While creating a TrackingValue value, an invalid attribute value was detected. "+
					"A TrackingValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("TrackingValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("TrackingValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra TrackingValue Attribute Value",
				"While creating a TrackingValue value, an extra attribute value was detected. "+
					"A TrackingValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra TrackingValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewTrackingValueUnknown(), diags
	}

	assignedCommentsAttribute, ok := attributes["assigned_comments"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`assigned_comments is missing from object`)

		return NewTrackingValueUnknown(), diags
	}

	assignedCommentsVal, ok := assignedCommentsAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`assigned_comments expected to be basetypes.BoolValue, was: %T`, assignedCommentsAttribute))
	}

	checklistsAttribute, ok := attributes["checklists"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`checklists is missing from object`)

		return NewTrackingValueUnknown(), diags
	}

	checklistsVal, ok := checklistsAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`checklists expected to be basetypes.BoolValue, was: %T`, checklistsAttribute))
	}

	subtasksAttribute, ok := attributes["subtasks"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`subtasks is missing from object`)

		return NewTrackingValueUnknown(), diags
	}

	subtasksVal, ok := subtasksAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`subtasks expected to be basetypes.BoolValue, was: %T`, subtasksAttribute))
	}

	if diags.HasError() {
		return NewTrackingValueUnknown(), diags
	}

	return TrackingValue{
		AssignedComments: assignedCommentsVal,
		Checklists:       checklistsVal,
		Subtasks:         subtasksVal,
		state:            attr.ValueStateKnown,
	}, diags
}

func NewTrackingValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) TrackingValue {
	object, diags := NewTrackingValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewTrackingValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t TrackingType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewTrackingValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewTrackingValueUnknown(), nil
	}

	if in.IsNull() {
		return NewTrackingValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewTrackingValueMust(TrackingValue{}.AttributeTypes(ctx), attributes), nil
}

func (t TrackingType) ValueType(ctx context.Context) attr.Value {
	return TrackingValue{}
}

var _ basetypes.ObjectValuable = TrackingValue{}

type TrackingValue struct {
	AssignedComments basetypes.BoolValue `tfsdk:"assigned_comments"`
	Checklists       basetypes.BoolValue `tfsdk:"checklists"`
	Subtasks         basetypes.BoolValue `tfsdk:"subtasks"`
	state            attr.ValueState
}

func (v TrackingValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 3)

	var val tftypes.Value
	var err error

	attrTypes["assigned_comments"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["checklists"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["subtasks"] = basetypes.BoolType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 3)

		val, err = v.AssignedComments.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["assigned_comments"] = val

		val, err = v.Checklists.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["checklists"] = val

		val, err = v.Subtasks.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["subtasks"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

